function escapeRegex(s){ return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

function normPath(p){
  var s=String(p==null?'':p).trim();
  if(!s) return '/';
  if(/^https?:\/\//i.test(s)) return s;
  if(s[0]!=='/') s='/'+s;
  if(s.length>1) s=s.replace(/\/+$/,'');
  return s||'/';
}
function stripLead(p){ return String(p||'').replace(/^\/+/,''); }

function section(title, lines){
  if(!lines || !lines.length) return [];
  return ['# ---- '+title+' ----'].concat(lines, ['']);
}
function ifModule(mod, lines, indent){
  if(!lines || !lines.length) return [];
  var pad=indent===false?'':'  ';
  return ['<IfModule '+mod+'>'].concat(lines.map(function(l){ return pad+l; }), ['</IfModule>']);
}

function genHttps(){
  return ['RewriteCond %{HTTPS} !=on',
          'RewriteCond %{HTTP:X-Forwarded-Proto} !https',
          'RewriteRule ^(.*)$ https://%{HTTP_HOST}%{REQUEST_URI} [R=301,L]'];
}

function genWww(mode){
  if(mode==='add')
    return ['RewriteCond %{HTTP_HOST} !^www\\. [NC]',
            'RewriteCond %{HTTP_HOST} !^localhost [NC]',
            'RewriteRule ^(.*)$ https://www.%{HTTP_HOST}%{REQUEST_URI} [R=301,L]'];
  if(mode==='remove')
    return ['RewriteCond %{HTTP_HOST} ^www\\.(.+)$ [NC]',
            'RewriteRule ^(.*)$ https://%1%{REQUEST_URI} [R=301,L]'];
  return [];
}

function genRedirect(r){
  var code=r.code||301, from=String(r.from||'').trim(), to=normPath(r.to||'/');
  if(!from) return [];
  var type=r.type||'exact';
  if(type==='regex') return ['RewriteRule '+from+' '+to+' [R='+code+',L]'];
  var pat=escapeRegex(stripLead(from));
  if(type==='prefix') return ['RewriteRule ^'+pat+'/?(.*)$ '+to+'/$1 [R='+code+',L,QSA]'];
  return ['RewriteRule ^'+pat+'/?$ '+to+' [R='+code+',L]'];
}

function genSpa(entry){
  var e=normPath(entry||'/index.html');
  return ['RewriteCond %{REQUEST_FILENAME} !-f',
          'RewriteCond %{REQUEST_FILENAME} !-d',
          'RewriteCond %{REQUEST_URI} !^/api/',
          'RewriteRule ^ '+e+' [L]'];
}

var CACHE_PRESETS = {
  'image/jpeg':'1 year','image/png':'1 year','image/gif':'1 year','image/webp':'1 year',
  'image/avif':'1 year','image/svg+xml':'1 year','image/x-icon':'1 year',
  'font/woff2':'1 year','font/woff':'1 year',
  'text/css':'1 month','application/javascript':'1 month','text/javascript':'1 month',
  'application/json':'0 seconds','text/html':'0 seconds'
};

function genCache(map){
  var m = map || CACHE_PRESETS;
  var keys=Object.keys(m);
  if(!keys.length) return [];
  var body=['ExpiresActive On','ExpiresDefault "access plus 1 week"'];
  keys.forEach(function(k){ body.push('ExpiresByType '+k+' "access plus '+m[k]+'"'); });
  var immutable=['<FilesMatch "\\.(css|js|woff2|png|jpg|jpeg|gif|webp|avif|svg)$">',
                 '  Header append Cache-Control "public, immutable"','</FilesMatch>'];
  return ifModule('mod_expires.c', body).concat(ifModule('mod_headers.c', immutable));
}

var GZIP_TYPES=['text/html','text/plain','text/css','text/xml','text/javascript',
  'application/javascript','application/json','application/xml','application/rss+xml',
  'image/svg+xml','application/x-font-ttf','font/woff2'];

function genGzip(types){
  var t=types&&types.length?types:GZIP_TYPES;
  var body=['AddOutputFilterByType DEFLATE '+t.join(' '),
            'BrowserMatch ^Mozilla/4 gzip-only-text/html',
            'Header append Vary Accept-Encoding'];
  var br=['AddOutputFilterByType BROTLI_COMPRESS '+t.join(' ')];
  return ifModule('mod_deflate.c', body).concat(ifModule('mod_brotli.c', br));
}

function genSecurity(o){
  o=o||{};
  var h=[];
  if(o.nosniff!==false) h.push('Header always set X-Content-Type-Options "nosniff"');
  if(o.frame!==false) h.push('Header always set X-Frame-Options "'+(o.frame||'SAMEORIGIN')+'"');
  if(o.referrer!==false) h.push('Header always set Referrer-Policy "'+(o.referrer||'strict-origin-when-cross-origin')+'"');
  if(o.permissions!==false) h.push('Header always set Permissions-Policy "geolocation=(), microphone=(), camera=()"');
  if(o.hsts){
    var v='max-age='+(o.hstsMaxAge||31536000);
    if(o.hstsSub!==false) v+='; includeSubDomains';
    if(o.hstsPreload) v+='; preload';
    h.push('Header always set Strict-Transport-Security "'+v+'"');
  }
  if(o.csp) h.push('Header always set Content-Security-Policy "'+o.csp+'"');
  if(o.coop) h.push('Header always set Cross-Origin-Opener-Policy "same-origin"');
  if(o.removeServer!==false){
    h.push('Header unset X-Powered-By');
    h.push('ServerSignature Off');
  }
  var srv=[];
  h=h.filter(function(l){ if(l.indexOf('ServerSignature')===0){ srv.push(l); return false; } return true; });
  return ifModule('mod_headers.c', h).concat(srv);
}

function genCors(o){
  o=o||{};
  if(!o.origin) return [];
  var h=['Header set Access-Control-Allow-Origin "'+o.origin+'"',
         'Header set Access-Control-Allow-Methods "'+(o.methods||'GET, POST, OPTIONS')+'"',
         'Header set Access-Control-Allow-Headers "'+(o.headers||'Content-Type, Authorization')+'"'];
  if(o.credentials) h.push('Header set Access-Control-Allow-Credentials "true"');
  if(o.maxAge) h.push('Header set Access-Control-Max-Age "'+o.maxAge+'"');
  return ifModule('mod_headers.c', h);
}

function genHotlink(o){
  o=o||{};
  var domains=(o.domains||[]).filter(function(d){ return d; });
  if(!domains.length) return [];
  var out=[];
  if(o.allowEmpty!==false) out.push('RewriteCond %{HTTP_REFERER} !^$');
  domains.forEach(function(d){
    out.push('RewriteCond %{HTTP_REFERER} !^https?://(www\\.)?'+escapeRegex(d)+' [NC]');
  });
  var ext=(o.extensions||['jpg','jpeg','png','gif','svg','webp','avif','mp4']).join('|');
  out.push('RewriteRule \\.('+ext+')$ '+(o.replacement?o.replacement+' [R,NC,L]':'- [F,NC,L]'));
  return out;
}

function genAuth(o){
  o=o||{};
  if(!o.file) return [];
  return ['AuthType Basic',
          'AuthName "'+(o.realm||'Restricted Area')+'"',
          'AuthUserFile '+o.file,
          'Require valid-user'];
}

function genBlockIps(ips){
  var list=(ips||[]).filter(function(x){ return x; });
  if(!list.length) return [];
  return ['<RequireAll>','  Require all granted']
    .concat(list.map(function(ip){ return '  Require not ip '+ip; }))
    .concat(['</RequireAll>']);
}

function genBlockAgents(agents){
  var list=(agents||[]).filter(function(x){ return x; });
  if(!list.length) return [];
  var out=[];
  list.forEach(function(a,i){
    out.push('RewriteCond %{HTTP_USER_AGENT} '+escapeRegex(a)+' [NC'+(i<list.length-1?',OR':'')+']');
  });
  out.push('RewriteRule ^ - [F,L]');
  return out;
}

function genErrorPages(map){
  var keys=Object.keys(map||{});
  if(!keys.length) return [];
  return keys.map(function(code){ return 'ErrorDocument '+code+' '+normPath(map[code]); });
}

function genOptions(o){
  o=o||{};
  var out=[];
  if(o.indexes===false || o.indexes==null) out.push('Options -Indexes');
  else out.push('Options +Indexes');
  if(o.followSymlinks!==false) out.push('Options +FollowSymLinks');
  if(o.dirIndex) out.push('DirectoryIndex '+o.dirIndex);
  if(o.charset) out.push('AddDefaultCharset '+o.charset);
  if(o.protectDotfiles!==false){
    out.push('<FilesMatch "^\\.(env|git|htaccess|htpasswd|DS_Store)">');
    out.push('  Require all denied');
    out.push('</FilesMatch>');
  }
  return out;
}

function build(cfg){
  cfg=cfg||{};
  var out=['# Generated by HtaccessForge - nano-tools',
           '# 单文件 · 零依赖 · 本地生成，未上传任何服务器',''];
  out=out.concat(section('目录与文件保护', genOptions(cfg.options)));
  var rw=[];
  if(cfg.https) rw=rw.concat(genHttps());
  if(cfg.www && cfg.www!=='none') rw=rw.concat(genWww(cfg.www));
  (cfg.redirects||[]).forEach(function(r){ rw=rw.concat(genRedirect(r)); });
  if(cfg.blockAgents && cfg.blockAgents.length) rw=rw.concat(genBlockAgents(cfg.blockAgents));
  if(cfg.hotlink && cfg.hotlink.domains && cfg.hotlink.domains.length) rw=rw.concat(genHotlink(cfg.hotlink));
  if(cfg.spa) rw=rw.concat(genSpa(cfg.spa===true?'/index.html':cfg.spa));
  if(rw.length){
    var body=['RewriteEngine On'];
    if(cfg.rewriteBase) body.push('RewriteBase '+normPath(cfg.rewriteBase));
    body=body.concat(rw);
    out=out.concat(section('重写规则', ifModule('mod_rewrite.c', body)));
  }
  if(cfg.security) out=out.concat(section('安全响应头', genSecurity(cfg.security)));
  if(cfg.cors && cfg.cors.origin) out=out.concat(section('CORS', genCors(cfg.cors)));
  if(cfg.gzip) out=out.concat(section('压缩', genGzip(cfg.gzipTypes)));
  if(cfg.cache) out=out.concat(section('缓存策略', genCache(cfg.cache===true?null:cfg.cache)));
  if(cfg.blockIps && cfg.blockIps.length) out=out.concat(section('IP 封禁', genBlockIps(cfg.blockIps)));
  if(cfg.auth && cfg.auth.file) out=out.concat(section('Basic 认证', genAuth(cfg.auth)));
  if(cfg.errorPages) out=out.concat(section('错误页', genErrorPages(cfg.errorPages)));
  while(out.length && out[out.length-1]==='') out.pop();
  return out.join('\n')+'\n';
}

