function explain(line){
  var s=String(line||'').trim();
  if(!s) return null;
  if(s[0]==='#') return '注释行';
  for(var i=0;i<EXPLAIN.length;i++){
    var m=EXPLAIN[i][0].exec(s);
    if(m){
      var t=EXPLAIN[i][1];
      for(var g=1;g<m.length;g++) t=t.replace('$'+g, m[g]);
      return t;
    }
  }
  return null;
}

function lint(text){
  var lines=String(text||'').split(/\r?\n/);
  var w=[], hasEngine=false, engineCount=0, sawRule=false, openTags=[];
  lines.forEach(function(raw, i){
    var n=i+1, s=raw.trim();
    if(!s || s[0]==='#') return;
    if(/^RewriteEngine\s+On/i.test(s)){ hasEngine=true; engineCount++; }
    if(/^RewriteRule/i.test(s)){
      sawRule=true;
      if(!hasEngine) w.push({line:n, level:'error', msg:'RewriteRule 出现在 RewriteEngine On 之前，规则不会生效'});
      var fl=/\[([^\]]*)\]\s*$/.exec(s);
      var flags=fl?fl[1]:'';
      if(/R=\d+/.test(flags) && !/\bL\b/.test(flags))
        w.push({line:n, level:'warn', msg:'重定向规则缺少 L 标志，后续规则会继续匹配，容易产生重定向链'});
      if(!fl) w.push({line:n, level:'info', msg:'RewriteRule 没有任何标志位，确认是否需要 [L] 终止匹配'});
      if(/R=301/.test(flags) && /\$\{/.test(s))
        w.push({line:n, level:'info', msg:'301 会被浏览器长期缓存，调试期间建议先用 R=302'});
    }
    if(/^Order\s+/i.test(s) || /^(Allow|Deny)\s+from/i.test(s))
      w.push({line:n, level:'error', msg:'Order/Allow/Deny 是 Apache 2.2 语法，2.4 起已移除，请改用 Require'});
    if(/^Options\s+.*\+Indexes/i.test(s))
      w.push({line:n, level:'warn', msg:'开启了目录列表 (+Indexes)，会暴露目录下全部文件名'});
    if(/^ErrorDocument\s+\d+\s+(?!["/]|https?:)/i.test(s))
      w.push({line:n, level:'warn', msg:'ErrorDocument 路径没有以 / 开头，Apache 会把它当作纯文本消息返回'});
    if(/^AuthUserFile\s+/i.test(s)){
      var p=s.replace(/^AuthUserFile\s+/i,'').trim();
      if(!/^\//.test(p)) w.push({line:n, level:'warn', msg:'AuthUserFile 建议使用绝对路径'});
      if(/(^|\/)(public|www|htdocs|public_html)\//i.test(p))
        w.push({line:n, level:'error', msg:'.htpasswd 位于站点可访问目录内，密码文件会被直接下载'});
    }
    if(/^(Header|RequestHeader)\b/i.test(s) && !openTags.some(function(t){ return /mod_headers/.test(t); }))
      w.push({line:n, level:'info', msg:'Header 指令未包在 <IfModule mod_headers.c> 中，模块缺失时会导致 500'});
    if(/^Expires(Active|ByType|Default)/i.test(s) && !openTags.some(function(t){ return /mod_expires/.test(t); }))
      w.push({line:n, level:'info', msg:'Expires 指令未包在 <IfModule mod_expires.c> 中，模块缺失时会导致 500'});
    if(/^php_(value|flag)\s/i.test(s))
      w.push({line:n, level:'warn', msg:'php_value/php_flag 在 PHP-FPM 下无效，请改用 .user.ini 或 php.ini'});
    if(/\s+$/.test(raw))
      w.push({line:n, level:'info', msg:'行尾存在多余空白'});
    var open=/^<([A-Za-z]+)[^>]*>$/.exec(s);
    var close=/^<\/([A-Za-z]+)>$/.exec(s);
    if(open && !/\/>$/.test(s)) openTags.push(open[1]==='IfModule' ? 'IfModule:'+s : open[1]);
    if(close){
      var last=openTags.pop();
      if(!last) w.push({line:n, level:'error', msg:'出现未配对的结束标签 '+close[0]});
      else if(String(last).split(':')[0]!==close[1])
        w.push({line:n, level:'error', msg:'标签嵌套不匹配：期望关闭 '+String(last).split(':')[0]+'，实际是 '+close[1]});
    }
  });
  if(openTags.length) w.push({line:lines.length, level:'error', msg:'有 '+openTags.length+' 个容器标签没有闭合：'+openTags.map(function(t){return String(t).split(':')[0];}).join(', ')});
  if(engineCount>1) w.push({line:0, level:'info', msg:'RewriteEngine On 出现了 '+engineCount+' 次，保留一次即可'});
  if(hasEngine && !sawRule) w.push({line:0, level:'info', msg:'开启了 RewriteEngine 但没有任何 RewriteRule'});
  return w;
}

function stats(text){
  var lines=String(text||'').split(/\r?\n/);
  var s={total:lines.length, directives:0, comments:0, blank:0, rules:0, conds:0, headers:0, modules:{}};
  lines.forEach(function(raw){
    var t=raw.trim();
    if(!t){ s.blank++; return; }
    if(t[0]==='#'){ s.comments++; return; }
    s.directives++;
    if(/^RewriteRule/i.test(t)) s.rules++;
    if(/^RewriteCond/i.test(t)) s.conds++;
    if(/^Header/i.test(t)) s.headers++;
    var m=/^<IfModule\s+([^>\s]+)/i.exec(t);
    if(m) s.modules[m[1]]=(s.modules[m[1]]||0)+1;
  });
  return s;
}

